const days=[
{title:['Архитектура','Ճարտարապետություն'],key:['Камень','Քար'],subtitle:['Город, написанный в камне','Քարի մեջ գրված քաղաքը'],idea:['От тихих улочек Конда до выразительных форм современной архитектуры. Читаем Ереван как книгу, в которой каждая эпоха оставила свой след.','Կոնդի լուռ փողոցներից մինչև ժամանակակից ճարտարապետական արտահայտիչ ձևերը։ Երևանը կարդում ենք որպես գիրք, որտեղ ամեն դարաշրջան թողել է իր հետքը։'],image:'cascade',stageTitles:[['История Еревана','Երևանի պատմությունը'],['Память города','Քաղաքի հիշողությունը'],['Город нового поколения','Նոր սերնդի քաղաքը']],stageCopy:[['Историческая застройка: от старых кварталов до монументальных ансамблей и центральных улиц.','Պատմական կառուցապատում՝ հին թաղամասերից մինչև մոնումենտալ համալիրներն ու կենտրոնական փողոցները։'],['Архитектура, скульптура и городские ансамбли как хранители культурной идентичности.','Ճարտարապետությունը, քանդակը և քաղաքային համալիրները՝ որպես մշակութային ինքնության պահապաններ։'],['Современные пространства, смелые формы и среда для новых поколений.','Ժամանակակից տարածքներ, համարձակ ձևեր և միջավայր նոր սերունդների համար։']]},
{title:['Музыка','Երաժշտություն'],key:['Звук','Ձայն'],subtitle:['Услышать ритм Еревана','Լսել Երևանի ռիթմը'],idea:['Народные мелодии, академическое наследие и джазовая импровизация. Слушаем, как меняется голос города.','Ժողովրդական մեղեդիներ, ակադեմիական ժառանգություն և ջազային իմպրովիզացիա։ Լսում ենք, թե ինչպես է փոխվում քաղաքի ձայնը։'],image:'music',stageTitles:[['Наследие Комитаса','Կոմիտասի ժառանգությունը'],['Поколение музыкантов','Երաժիշտների սերունդը'],['Джаз без границ','Ջազն առանց սահմանների']],stageCopy:[['Народные мелодии и работа Комитаса по сохранению музыкальной традиции.','Ժողովրդական մեղեդիներն ու երաժշտական ավանդույթի պահպանման Կոմիտասի աշխատանքը։'],['Музыкальное образование, исполнение и знакомство с жизнью консерватории.','Երաժշտական կրթություն, կատարողական արվեստ և ծանոթություն կոնսերվատորիայի կյանքին։'],['Левон Малхасян, ереванская джазовая сцена и современные музыкальные эксперименты.','Լևոն Մալխասյան, Երևանի ջազային տեսարան և ժամանակակից երաժշտական փորձարկումներ։']]},
{title:['Кино и анимация','Կինո և անիմացիա'],key:['Образ','Պատկեր'],subtitle:['Увидеть больше, чем кадр','Տեսնել կադրից ավելին'],idea:['Как культурный код становится языком кино? От коллажей Параджанова до раскадровок анимации — учимся рассказывать истории образами.','Ինչպե՞ս է մշակութային կոդը դառնում կինոյի լեզու։ Փարաջանովի կոլաժներից մինչև անիմացիայի կադրային պլանավորում՝ սովորում ենք պատմել պատկերներով։'],image:'cinema',stageTitles:[['Мир Параджанова','Փարաջանովի աշխարհը'],['«Цвет граната»','«Նռան գույնը»'],['Ожившие образы','Կենդանացած պատկերներ']],stageCopy:[['Коллажи, эскизы и метафоры: знакомимся с авторским подходом режиссёра.','Կոլաժներ, էսքիզներ և փոխաբերություններ․ ծանոթանում ենք ռեժիսորի հեղինակային մոտեցմանը։'],['Смотрим и разбираем символы, композицию кадра и ритм визуального повествования.','Դիտում և վերլուծում ենք խորհրդանիշները, կադրի կառուցվածքն ու տեսողական պատմության ռիթմը։'],['Исследуем этапы создания анимации и авторский язык студии Саакянца.','Ուսումնասիրում ենք անիմացիայի ստեղծման փուլերն ու Սահակյանց ստուդիայի հեղինակային լեզուն։']],practice:['Практика дня: вертикальный видеоролик или рилс по мотивам путешествия. Публикация — с согласия участников и с учётом прав на материалы.','Օրվա գործնական աշխատանքը՝ ուղղահայաց տեսանյութ՝ ճանապարհորդության մոտիվներով։ Հրապարակումը՝ մասնակիցների համաձայնությամբ և նյութերի իրավունքների պահպանմամբ։']},
{title:['Живопись и дизайн','Գեղանկարչություն և դիզայն'],key:['Цвет','Գույն'],subtitle:['От древних росписей к цифре','Հնագույն որմնանկարներից դեպի թվային աշխարհ'],idea:['Древние художественные коды, палитры Сарьяна и творческие технологии. Исследуем, как цвет соединяет разные эпохи.','Հնագույն գեղարվեստական կոդեր, Սարյանի գունապնակ և ստեղծագործական տեխնոլոգիաներ։ Ուսումնասիրում ենք, թե ինչպես է գույնը կապում տարբեր դարաշրջանները։'],image:'art',stageTitles:[['Художественный код Урарту','Ուրարտուի գեղարվեստական կոդը'],['Сарьян и Айвазовский','Սարյան և Այվազովսկի'],['Творчество и технологии','Ստեղծագործություն և տեխնոլոգիա']],stageCopy:[['Крепость Эребуни, фрагменты росписей и мастер-класс по керамике.','Էրեբունի ամրոց, որմնանկարների հատվածներ և խեցեգործության վարպետաց դաս։'],['Композиция, свет и цвет на примере произведений Национальной галереи.','Կոմպոզիցիա, լույս և գույն՝ Ազգային պատկերասրահի ստեղծագործությունների օրինակով։'],['Цифровой дизайн и междисциплинарные творческие лаборатории TUMO.','Թվային դիզայն և TUMO-ի միջառարկայական ստեղծագործական լաբորատորիաներ։']],practice:['Практика дня: керамика и роспись; скетчинг в галерее — по согласованию с площадкой.','Օրվա գործնական աշխատանքը՝ խեցեգործություն և նկարազարդում։ Սքեթչինգը պատկերասրահում՝ ըստ հաստատության համաձայնության։']},
{title:['Мода и ремёсла','Նորաձևություն և արհեստներ'],key:['Нить','Թել'],subtitle:['Следовать за нитью традиций','Հետևել ավանդույթների թելին'],idea:['Орнаменты, натуральные красители, национальный костюм. Находим связь между памятью материала и современным дизайном.','Նախշեր, բնական ներկեր, ազգային տարազ։ Բացահայտում ենք նյութի հիշողության և ժամանակակից դիզայնի կապը։'],image:'fashion',stageTitles:[['Память в орнаменте','Հիշողությունը նախշի մեջ'],['Искусство ковра','Գորգի արվեստը'],['Традиция в новом крое','Ավանդույթը նոր ձևվածքով']],stageCopy:[['Ковры, керамика, резьба по дереву и ювелирное искусство в музее Шарамбеяна.','Գորգեր, խեցեղեն, փայտի փորագրություն և ոսկերչություն Շարամբեյանի թանգարանում։'],['Традиционные техники, материалы и процесс создания армянского ковра.','Ավանդական տեխնիկաներ, նյութեր և հայկական գորգի ստեղծման ընթացքը։'],['Современные интерпретации национальной одежды, аксессуаров и фактур.','Ազգային հագուստի, աքսեսուարների և գործվածքների ժամանակակից մեկնաբանություններ։']]}
];

const keyStories=[
 ['Камень сохраняет время: в фасадах, дворах, лестницах и площадях можно прочитать, как менялись представления о городе. Мы сопоставим исторические кварталы, монументальные ансамбли и современные пространства — и попробуем увидеть за формой человеческий замысел.','Քարը պահպանում է ժամանակը․ շենքի ճակատային հատվածները, բակերը, աստիճաններն ու հրապարակները պատմում են քաղաքի մասին պատկերացումների փոփոխության մասին։ Համեմատելու ենք պատմական թաղամասերը, մոնումենտալ համալիրներն ու ժամանակակից տարածքները՝ ձևի հետևում տեսնելով մարդու մտահղացումը։'],
 ['Звук связывает народную мелодию, профессиональное исполнение и импровизацию. Важно не только услышать произведение, но и понять, как музыкальная традиция передаётся новому поколению и получает собственное современное звучание.','Ձայնը կապում է ժողովրդական մեղեդին, մասնագիտական կատարումն ու իմպրովիզացիան։ Կարևոր է ոչ միայն լսել ստեղծագործությունը, այլև հասկանալ, թե ինչպես է երաժշտական ավանդույթը փոխանցվում նոր սերնդին և ստանում ժամանակակից հնչողություն։'],
 ['Образ помогает рассказывать без лишних слов. Коллаж, предмет, фактура и цвет становятся частью повествования. От авторского мира Параджанова мы перейдём к языку анимации и собственному короткому видео по мотивам дня.','Պատկերը օգնում է պատմել առանց ավելորդ բառերի։ Կոլաժը, առարկան, հյուսվածքն ու գույնը դառնում են պատմության մաս։ Փարաջանովի հեղինակային աշխարհից անցնելու ենք անիմացիայի լեզվին և օրվա մոտիվներով մեր կարճ տեսանյութին։'],
 ['Цвет позволяет проследить путь от древней росписи до цифровой композиции. Мы будем замечать отношения оттенков, света и формы, разбирать художественные решения и превращать наблюдения в наброски и творческие эксперименты.','Գույնը թույլ է տալիս հետևել հնագույն որմնանկարից մինչև թվային կոմպոզիցիա ձգվող ճանապարհին։ Նկատելու ենք երանգների, լույսի ու ձևի հարաբերությունները, վերլուծելու գեղարվեստական լուծումները և դիտարկումները վերածելու էսքիզների ու փորձարկումների։'],
 ['Нить соединяет мастерство рук и память орнамента. В тканях, коврах и костюме сохраняются способы работы с материалом. Исследуем, как эти знания продолжают жить в современном дизайне одежды и аксессуаров.','Թելը կապում է ձեռքի վարպետությունն ու նախշի հիշողությունը։ Գործվածքներում, գորգերում և տարազում պահպանվում են նյութի հետ աշխատանքի գիտելիքները։ Ուսումնասիրելու ենք, թե ինչպես են դրանք շարունակում ապրել ժամանակակից հագուստի և աքսեսուարների դիզայնում։']
];
function enrichContent(){
 const add=(selector,html)=>document.querySelector(selector)?.insertAdjacentHTML('beforeend',html);
 const paragraph=(ru,hy,cls='extended-copy')=>`<p class="${cls}">${t(ru,hy)}</p>`;
 add('.hero-bottom>div:first-child',paragraph('Здесь у каждого дня свой язык: камень, звук, образ, цвет и нить. Пять способов увидеть Ереван — и найти в его культуре идеи для собственного творчества.','Այստեղ ամեն օրն ունի իր լեզուն՝ քար, ձայն, պատկեր, գույն և թել։ Երևանը տեսնելու և նրա մշակույթում սեփական ստեղծագործության գաղափարներ գտնելու հինգ ուղի։','hero-extra'));
 add('.legend-explanation',paragraph('Это путешествие-исследование: собираем подсказки прошлого, замечаем перемены настоящего и представляем город завтрашнего дня. Каждый найденный ключ меняет угол зрения, а вместе они складываются в целостный образ Еревана.','Սա հետազոտական ճանապարհորդություն է․ հավաքում ենք անցյալի հուշումները, նկատում ներկայի փոփոխությունները և պատկերացնում վաղվա քաղաքը։ Յուրաքանչյուր գտնված բանալի փոխում է դիտանկյունը, իսկ միասին դրանք կազմում են Երևանի ամբողջական պատկերը։'));
 add('#about .about-top>div:last-child',`<details class="more-story"><summary>${t('Как устроено путешествие','Ինչպես է կառուցված ճանապարհորդությունը')} <span aria-hidden="true">+</span></summary><div>${paragraph('Вместо перечня достопримечательностей — пять связанных историй. В музеях и культурных институциях мы исследуем наследие, в образовательных центрах и творческих пространствах знакомимся с современными практиками, а в заданиях пробуем собственные решения.','Տեսարժան վայրերի ցանկի փոխարեն՝ հինգ փոխկապակցված պատմություն։ Թանգարաններում ու մշակութային հաստատություններում ուսումնասիրում ենք ժառանգությունը, կրթական կենտրոններում ու ստեղծագործական տարածքներում ծանոթանում ժամանակակից փորձին, իսկ առաջադրանքներում փորձում սեփական լուծումները։')}${paragraph('Маршрут рассчитан на молодых исследователей 18–35 лет: студентов, молодых специалистов, учёных и представителей творческих профессий. Его лёгкий уровень сложности позволяет сосредоточиться на наблюдении, обсуждении и создании работ.','Երթուղին նախատեսված է 18–35 տարեկան երիտասարդ հետազոտողների՝ ուսանողների, մասնագետների, գիտնականների և ստեղծագործական մասնագիտությունների ներկայացուցիչների համար։ Թեթև բարդության մակարդակը թույլ է տալիս կենտրոնանալ դիտարկման, քննարկման և ստեղծագործելու վրա։')}</div></details>`);
 add('#program .section-head',`<div class="program-intro">${paragraph('У каждого дня три временных слоя. Утром знакомимся с истоками и культурными символами, днём изучаем актуальные подходы, а затем обращаемся к новым формам и технологиям. Нажмите на направление, чтобы раскрыть расписание, а на название места — чтобы узнать подробности.','Յուրաքանչյուր օր ունի երեք ժամանակային շերտ։ Առավոտյան ծանոթանում ենք ակունքներին ու մշակութային խորհրդանիշներին, ցերեկը՝ արդի մոտեցումներին, ապա՝ նոր ձևերին ու տեխնոլոգիաներին։ Սեղմեք ուղղությունը՝ ժամանակացույցը, իսկ վայրի անունը՝ մանրամասները բացելու համար։')}</div>`);
 add('#route-map .map-heading>div',paragraph('Карта связывает программу с реальными местами: выберите день и временной этап, откройте маркер или перейдите к нему из карточки. Обозначены пешие участки и трансферы; точные входы и условия посещения уточняют организаторы.','Քարտեզը կապում է ծրագիրն իրական վայրերի հետ․ ընտրեք օրն ու փուլը, բացեք նշիչը կամ անցեք դրան վայրի քարտից։ Նշված են հետիոտնային հատվածներն ու տրանսֆերները․ մուտքերն ու այցելության պայմանները ճշտում են կազմակերպիչները։'));
 add('#education .section-head',`<div class="education-intro">${paragraph('Образовательный маршрут соединяет наблюдение, анализ и практику. Участники учатся замечать культурные символы, сравнивать художественные приёмы и объяснять собственные творческие решения. Ежедневное обсуждение помогает связать впечатления с полученным опытом.','Կրթական երթուղին միավորում է դիտարկումը, վերլուծությունն ու գործնական աշխատանքը։ Մասնակիցները սովորում են նկատել մշակութային խորհրդանիշները, համեմատել գեղարվեստական հնարքները և բացատրել սեփական ստեղծագործական լուծումները։ Ամենօրյա քննարկումը կապում է տպավորություններն ու ձեռք բերված փորձը։')}</div>`);
 const eduExtra=[
 ['На каждой площадке обращаем внимание на конкретный объект, произведение или символ. Сравниваем его исторический контекст и современное прочтение, чтобы увидеть культурное наследие как источник идей.','Յուրաքանչյուր հարթակում ուշադրություն ենք դարձնում կոնկրետ առարկայի, ստեղծագործության կամ խորհրդանիշի։ Համեմատում ենք պատմական համատեքստն ու ժամանակակից ընթերցումը՝ ժառանգության մեջ գաղափարների աղբյուր տեսնելու համար։'],
 ['Практические задания помогают проверить наблюдения: попробовать выразительность материала, построить композицию, поработать с цветом и ритмом. Формат мастер-классов определяется возможностями площадок.','Գործնական առաջադրանքները թույլ են տալիս ստուգել դիտարկումները՝ փորձել նյութի արտահայտչականությունը, կառուցել կոմպոզիցիա, աշխատել գույնի և ռիթմի հետ։ Վարպետաց դասերի ձևաչափը կախված է հարթակների հնարավորություններից։'],
 ['В финале участник или команда представляет собственную работу и рассказывает, какие культурные наблюдения легли в её основу. Важен не только результат, но и путь от впечатления к осмысленной идее.','Վերջում մասնակիցը կամ թիմը ներկայացնում է սեփական աշխատանքը և պատմում այն ձևավորած մշակութային դիտարկումների մասին։ Կարևոր է ոչ միայն արդյունքը, այլև տպավորությունից դեպի գիտակցված գաղափար տանող ճանապարհը։']
 ];document.querySelectorAll('.edu-item').forEach((el,i)=>el.insertAdjacentHTML('beforeend',paragraph(...eduExtra[i])));
 add('#partners .section-head',`<div class="partners-intro">${paragraph('Маршрут находится на пересечении университетского образования, культурного исследования и студенческого туризма. Пять направлений помогают увидеть Ереван как пространство для межкультурного диалога и творческого обмена.','Երթուղին միավորում է համալսարանական կրթությունը, մշակութային հետազոտությունն ու ուսանողական զբոսաշրջությունը։ Հինգ ուղղությունները օգնում են Երևանը տեսնել որպես միջմշակութային երկխոսության և ստեղծագործական փոխանակման տարածք։')}</div>`);
 const partnerGrid=document.querySelector('.partner-grid');const partnerItems=[...partnerGrid.children];[1,5,3,0,2,4].forEach(i=>partnerGrid.append(partnerItems[i]));
 document.querySelectorAll('.partner').forEach((el,i)=>{const img=el.querySelector('img');const name=img.alt;el.insertAdjacentHTML('afterbegin',`<span class="partner-index">0${i+1}</span>`);el.insertAdjacentHTML('beforeend',`<p class="partner-name">${esc(name)}</p>`);});
}

const wowStops=[[7],[2],[0],[2],[2]];
const stages=[['Прошлое','Անցյալ'],['Настоящее','Ներկա'],['Будущее','Ապագա']];
const nav=[['home','Главная','Գլխավոր'],['legend','Легенда','Լեգենդ'],['about','О маршруте','Երթուղու մասին'],['program','Программа','Ծրագիր'],['education','Образование','Կրթություն'],['partners','Партнёры','Գործընկերներ']];
function logo(){return `<a class="brand" href="#home" aria-label="${t('Барев, Ереван — главная','Բարև, Երևան — գլխավոր')}"><strong>${t('Барев, Ереван','Բարև, Երևան')}<span class="logo-dot">✳</span></strong></a>`;}
let navObserver;
function render(){
 window.SiteMotion?.destroy();navObserver?.disconnect();
 document.documentElement.lang=lang;document.title=t('Барев, Ереван — пять ключей к душе города','Բարև, Երևան — քաղաքի հոգու հինգ բանալի');
 document.querySelector('meta[name=description]').content=t('Пять дней, пять направлений культуры и один Ереван. Культурно-образовательный маршрут: архитектура, музыка, кино, живопись и мода.','Հինգ օր, մշակույթի հինգ ուղղություն և մեկ Երևան։ Մշակութային և կրթական երթուղի՝ ճարտարապետություն, երաժշտություն, կինո, գեղանկարչություն և նորաձևություն։');
 document.getElementById('app').innerHTML=`<div class="reading-progress" aria-hidden="true"></div>
 <header class="header"><div class="wrap nav-wrap">${logo()}<nav class="nav" id="navigation" aria-label="${t('Основная навигация','Հիմնական նավարկում')}">${nav.map(n=>`<a href="#${n[0]}">${t(n[1],n[2])}</a>`).join('')}</nav><div class="language" aria-label="${t('Язык сайта','Կայքի լեզուն')}"><button data-lang="ru" lang="ru" aria-label="Русский" aria-pressed="${lang==='ru'}">RU</button><button data-lang="hy" lang="hy" aria-label="Հայերեն" aria-pressed="${lang==='hy'}">ՀԱՅ</button></div><button class="menu-button" aria-label="${t('Открыть меню','Բացել ընտրացանկը')}" aria-controls="navigation" aria-expanded="false">☰</button></div></header>
 <main id="main"><section id="home" class="hero wrap design-hero"><div class="hero-topline"><span>40°10′55″ N / 44°30′47″ E</span><span>${t('Культурно-образовательный маршрут · Армения · Ереван · 5 дней','Մշակութային և կրթական երթուղի · Հայաստան · Երևան · 5 օր')}</span><span>${t('05 дней · 05 направлений · 18–35 лет','05 օր · 05 ուղղություն · 18–35 տարեկան')}</span></div><div class="hero-glow" aria-hidden="true"></div><div class="scene" aria-hidden="true"><svg viewBox="0 0 1100 420"><g data-p="-0.08"><g class="sun" transform="translate(770 120)"><circle r="62" style="fill:var(--pom)"/><path d="M-14-60L-9-80 0-64 9-80 14-60" style="fill:none;stroke:var(--pom);stroke-width:4;stroke-linejoin:round"/><path d="M-34-8q34 22 68 0M-40 16q40 24 80 0" style="fill:none;stroke:var(--fg);stroke-opacity:.3;stroke-width:2"/></g></g><g data-p="0.12"><polygon points="600,420 820,250 1000,420" style="fill:var(--card);stroke:var(--line)"/><polygon points="150,420 500,150 590,195 780,420" style="fill:var(--card);stroke:var(--tuff);stroke-opacity:.5"/><polygon points="430,205 500,150 590,195 560,218 515,200 478,228" style="fill:var(--fg);opacity:.85"/></g><g data-p="0.28"><path d="M0 420V350H90V335H190V318H290V345H420V330H540V360H700V340H860V365H1100V420Z" style="fill:var(--bg);stroke:var(--tuff);stroke-opacity:.55"/></g></svg></div><div class="hero-main"><span class="eyebrow">${t('Где прошлое встречает будущее','Որտեղ անցյալը հանդիպում է ապագային')}</span><h1><span>${t('Барев,','Բարև,')}</span><span class="serif">${t('Ереван.','Երևան։')}</span></h1><div class="hero-bottom"><div><h2>${t('Пять ключей<br>к душе города','Հինգ բանալի՝<br>քաղաքի հոգու համար')}</h2><p>${t('Пять дней, пять направлений культуры и один город, в котором прошлое становится идеей будущего.','Հինգ օր, մշակույթի հինգ ուղղություն և մեկ քաղաք, որտեղ անցյալը դառնում է ապագայի գաղափար։')}</p></div><div class="hero-actions"><a class="btn primary" href="#program">${t('Исследовать маршрут','Ուսումնասիրել երթուղին')} ↗</a><a class="btn" href="#legend">${t('Открыть легенду','Բացահայտել լեգենդը')} ↓</a></div></div></div></section>
 <section id="legend" class="legend section"><div class="wrap"><span class="section-index">01 / ${t('Легенда маршрута','Երթուղու լեգենդը')}</span><h2>${t('Невидимая дверь,<br>которую открывают<br>пятью ключами.','Անտեսանելի դուռ,<br>որը բացվում է<br>հինգ բանալիներով։')}</h2><p class="legend-statement">${t('У Еревана она невидимая. За ней хранится душа города. Открыть её можно только пятью ключами: камнем, звуком, образом, цветом и нитью.','Երևանի դուռն անտեսանելի է։ Դրա հետևում քաղաքի հոգին է։ Այն կարելի է բացել միայն հինգ բանալիներով՝ քարով, ձայնով, պատկերով, գույնով և թելով։')}</p></div><div class="marquee" aria-hidden="true"><div>${[0,1,2,3].map(()=>days.map(d=>`<span>${pair(d.key)}</span>`).join('')).join('')}</div></div><div class="marquee marquee-reverse" aria-hidden="true"><div>${[0,1,2,3].map(()=>days.map(day=>`<span>${day.key[1]}</span>`).join('')).join('')}</div></div><div class="wrap"><div class="legend-explanation"><p>${t('Каждый ключ спрятан в одной из сфер культуры. Чтобы найти их, нужно увидеть город сразу в трёх временах — прошлом, настоящем и будущем.','Յուրաքանչյուր բանալի թաքնված է մշակույթի մի ոլորտում։ Դրանք գտնելու համար պետք է քաղաքը տեսնել միանգամից երեք ժամանակներում՝ անցյալում, ներկայում և ապագայում։')}</p><p>${t('Когда ключи окажутся вместе, дверь откроется. А что находится за ней — зависит от тех, кто пройдёт этот путь.','Երբ բանալիները միավորվեն, դուռը կբացվի։ Իսկ թե ինչ կա դրա հետևում՝ կախված է այս ճանապարհն անցնողներից։')}</p></div><div class="key-art-grid">${days.map((day,i)=>`<a class="key-art" href="#chapter-${i}" style="--accent:${chapterColors[i]}"><span class="key-art-number">0${i+1}</span><div class="ill">${keyArt(i)}</div><div class="key-art-caption"><strong>${pair(day.key)}</strong><span>${pair(day.title)}</span></div></a>`).join('')}</div><div class="keys">${days.map((day,i)=>`<div class="key-entry" style="--accent:${chapterColors[i]}"><button class="key-card" aria-expanded="false" aria-controls="key-detail-${i}"><span class="key-number">0${i+1}</span><h3>${pair(day.key)}</h3><small>${pair(day.title)}</small><span class="key-plus" aria-hidden="true">+</span></button><div class="key-detail" id="key-detail-${i}" hidden><div class="key-detail-inner"><div><p>${pair(day.idea)}</p><p>${pair(keyStories[i])}</p></div><div class="ill">${keyArt(i)}</div></div></div></div>`).join('')}</div><div class="legend-bottom"><a class="btn primary" href="#program">${t('Найти пять ключей','Գտնել հինգ բանալիները')} ↗</a></div></div></section>
 <section id="about" class="section"><div class="wrap"><span class="section-index">02 / ${t('О маршруте','Երթուղու մասին')}</span><div class="about-top"><div><h2>${t('Не просто увидеть.<br>Почувствовать.<br>Создать.','Տեսնել։<br>Զգալ։<br>Ստեղծել։')}</h2><div class="about-image"><img src="assets/cascade.webp" alt="${t('Каскад в вечернем свете','Կասկադը երեկոյան լույսի ներքո')}" loading="lazy" width="1200" height="1600"><span>${t('Каскад · Ереван','Կասկադ · Երևան')}</span></div></div><div><p>${t('«Барев, Ереван» — путешествие в армянский культурный код через архитектуру, музыку, кино и мультипликацию, живопись и дизайн, моду и декоративно-прикладное искусство.','«Բարև, Երևան»-ը ճանապարհորդություն է դեպի հայկական մշակութային կոդը՝ ճարտարապետության, երաժշտության, կինոյի և անիմացիայի, գեղանկարչության և դիզայնի, նորաձևության և դեկորատիվ-կիրառական արվեստի միջոցով։')}</p><p>${t('Каждый день — отдельная глава, построенная по принципу «прошлое — настоящее — будущее». Музеи, культурные институции и творческие пространства становятся местом для исследования, практики и собственных открытий.','Ամեն օրը առանձին գլուխ է՝ «անցյալ — ներկա — ապագա» սկզբունքով։ Թանգարանները, մշակութային հաստատություններն ու ստեղծագործական տարածքները դառնում են հետազոտության, գործնական աշխատանքի և սեփական բացահայտումների վայրեր։')}</p><div class="stats">${[['5',t('дней в Ереване, Армения','օր Երևանում, Հայաստան')],['≤40',t('участников','մասնակից')],['18–35',t('лет','տարեկան')],['RU / ՀԱՅ',t('языки проведения','ծրագրի լեզուները')],[t('Лёгкий','Թեթև'),t('уровень сложности','բարդության մակարդակ')],[t('Весь год','Ամբողջ տարին'),t('сезонность маршрута','երթուղու սեզոնայնությունը')]].map(v=>`<div class="stat"><b${v[0].length>7?' style="font-size:27px"':''}>${v[0]}</b><span>${v[1]}</span></div>`).join('')}</div></div></div><div class="about-features">${[[t('Исследуем','Հետազոտում ենք'),t('Читаем культурное наследие через конкретные объекты, произведения и символы.','Կարդում ենք մշակութային ժառանգությունը՝ առարկաների, ստեղծագործությունների և խորհրդանիշների միջոցով։')],[t('Пробуем','Փորձում ենք'),t('Осваиваем творческие инструменты на мастер-классах и в практических заданиях.','Վարպետաց դասերում և գործնական առաջադրանքներում յուրացնում ենք ստեղծագործական գործիքներ։')],[t('Создаём','Ստեղծում ենք'),t('Пробуем себя в креативных профессиях и представляем собственные работы.','Մեզ փորձում ենք ստեղծագործական մասնագիտություններում և ներկայացնում սեփական աշխատանքները։')]].map((v,i)=>`<article class="feature"><span class="eyebrow">0${i+1}</span><h3>${v[0]}</h3><p>${v[1]}</p></article>`).join('')}</div></div></section>
 <section id="program" class="program section"><div class="wrap"><span class="section-index">03 / ${t('Программа путешествия','Ճանապարհորդության ծրագիրը')}</span><div class="section-head"><h2>${t('Пять дней.<br>Пять новых взглядов.','Հինգ օր։<br>Հինգ նոր հայացք։')}</h2><p>${t('Выберите свой ключ. В каждой главе — прошлое, настоящее и будущее города, места и люди, которые раскрывают его характер.','Ընտրեք ձեր բանալին։ Յուրաքանչյուր գլխում՝ քաղաքի անցյալը, ներկան ու ապագան, նրա բնավորությունը բացահայտող վայրերն ու մարդիկ։')}</p></div><div id="day-chapters"></div><div id="route-map" class="map-section"><div class="map-heading"><div><h3>${t('Город на ладони','Քաղաքը՝ ափերիդ մեջ')}</h3><p>${t('Выбирайте этап и открывайте остановки на карте.','Ընտրեք փուլը և բացահայտեք կանգառները քարտեզի վրա։')}</p></div><a id="open-map" class="text-link" target="_blank" rel="noopener">${t('На весь экран','Ամբողջ էկրանով')} ↗</a></div><div class="map-days" role="group" aria-label="${t('День на карте','Օրը քարտեզի վրա')}">${days.map((day,i)=>`<button class="filter map-day" data-map-day="${i}" aria-pressed="${i===currentDay}">${t('День','Օր')} ${i+1} · ${pair(day.key)}</button>`).join('')}</div><div class="map-tools" role="group" aria-label="${t('Этапы маршрута','Երթուղու փուլերը')}">${[t('Все этапы','Բոլոր փուլերը'),...stages.map(pair)].map((s,i)=>`<button class="filter" data-stage="${i-1}" aria-pressed="${currentStage===i-1}">${s}</button>`).join('')}</div><iframe id="map-frame" class="map-frame" title="${t('Интерактивная карта маршрута','Երթուղու ինտերակտիվ քարտեզ')}" loading="lazy"></iframe><div id="selected-stop" class="selected-stop" aria-live="polite"></div><div class="map-footer"><span><b class="wow">WOW</b> ${t('— наша подборка ярких точек маршрута.','— երթուղու վառ կանգառների մեր ընտրանին։')}<br>${t('Подложка и маршруты хранятся локально · © OpenStreetMap contributors','Քարտեզն ու երթուղիները պահվում են տեղային · © OpenStreetMap contributors')}</span><span>${t('Пути и входы на площадки уточняются организаторами.','Ճանապարհներն ու մուտքերը ճշտվում են կազմակերպիչների կողմից։')}</span></div></div></div></section>
 <section id="education" class="education section"><div class="wrap"><span class="section-index">04 / ${t('Образовательная программа','Կրթական ծրագիր')}</span><div class="section-head"><h2>${t('Впечатления станут<br>вашим опытом.','Տպավորությունները<br>կդառնան ձեր փորձը։')}</h2><p>${t('Культурное путешествие и практический интенсив: от первого наблюдения до собственной творческой работы.','Մշակութային ճանապարհորդություն և գործնական ինտենսիվ՝ առաջին դիտարկումից մինչև սեփական ստեղծագործական աշխատանք։')}</p></div><div class="edu-grid">${[
[t('Изучаем','Ուսումնասիրում ենք'),t('Учимся видеть культурный код.','Սովորում ենք տեսնել մշակութային կոդը։'),[t('Наследие и символы армянской культуры','Հայկական մշակույթի ժառանգությունն ու խորհրդանիշները'),t('Связь традиций и современных практик','Ավանդույթների ու ժամանակակից փորձի կապը'),t('Работу архитекторов, музыкантов, режиссёров и дизайнеров','Ճարտարապետների, երաժիշտների, ռեժիսորների և դիզայներների աշխատանքը')]],
[t('Пробуем','Փորձում ենք'),t('Переводим наблюдения в практику.','Դիտարկումները վերածում ենք գործնական աշխատանքի։'),[t('Керамику, роспись, скетчинг и цвет','Խեցեգործություն, նկարազարդում, սքեթչինգ և գույն'),t('Визуальный язык кино и анимации','Կինոյի և անիմացիայի տեսողական լեզուն'),t('Звук, материал, орнамент и инструменты дизайна','Ձայն, նյութ, նախշ և դիզայնի գործիքներ')]],
[t('Создаём','Ստեղծում ենք'),t('Находим собственный творческий голос.','Գտնում ենք մեր ստեղծագործական ձայնը։'),[t('Керамическое изделие с росписью и скетчи','Նկարազարդ խեցեղեն և սքեթչեր'),t('Вертикальный видеоролик по мотивам дня','Օրվա մոտիվներով ուղղահայաց տեսանյութ'),t('Итоговую работу или командную презентацию','Ամփոփիչ աշխատանք կամ թիմային ներկայացում')]]].map((v,i)=>`<article class="edu-item"><span>0${i+1} /</span><h3>${v[0]}</h3><p>${v[1]}</p><ul>${v[2].map(s=>`<li>${s}</li>`).join('')}</ul></article>`).join('')}</div><div class="education-note"><strong>30 ${t('акад. часов','ակադ. ժամ')}</strong><p>${t('По два академических часа на каждой из трёх тематических площадок в день. Мастер-классы, обсуждения и ежедневная рефлексия. Финальная презентация 1,5–2 часа предусмотрена дополнительно; её место в расписании и общий объём программы согласуются с организаторами. Состав итоговых работ зависит от возможностей площадок.','Օրական երեք թեմատիկ հարթակներից յուրաքանչյուրում՝ երկու ակադեմիական ժամ։ Վարպետաց դասեր, քննարկումներ և ամենօրյա անդրադարձ։ Ամփոփիչ ներկայացման 1,5–2 ժամը նախատեսվում է լրացուցիչ․ ժամանակացույցն ու ընդհանուր ծավալը համաձայնեցվում են կազմակերպիչների հետ։ Աշխատանքների ցանկը կախված է հարթակների հնարավորություններից։')}</p></div><details class="competencies"><summary>${t('Какие навыки вы увезёте с собой','Ի՞նչ հմտություններ ձեռք կբերեք')}</summary><ul>${[t('Чтение культурного кода через визуальные и звуковые символы','Մշակութային կոդի ընթերցում՝ տեսողական և ձայնային խորհրդանիշներով'),t('Понимание связи прошлого, настоящего и будущего в культуре','Մշակույթի անցյալի, ներկայի և ապագայի կապի ըմբռնում'),t('Кросс-культурная коммуникация','Միջմշակութային հաղորդակցություն'),t('Основы композиции, цвета и визуального повествования','Կոմպոզիցիայի, գույնի և տեսողական պատմության հիմունքներ'),t('Междисциплинарная командная работа','Միջառարկայական թիմային աշխատանք'),t('Применение культурного наследия в творческих проектах','Մշակութային ժառանգության կիրառում ստեղծագործական նախագծերում')].map(s=>`<li>${s}</li>`).join('')}</ul></details><div class="final-keys"><h3>${t('Пять ключей. Один город.<br>Новое прочтение культуры.','Հինգ բանալիներ։ Մեկ քաղաք։<br>Մշակույթի նոր ընթերցում։')}</h3><div class="final-symbols" aria-hidden="true">${days.map((_,i)=>icon(i)).join('')}</div></div></div></section>
 <section id="partners" class="partners section"><div class="wrap"><span class="section-index">05 / ${t('Вместе открываем новое','Միասին բացահայտում ենք նորը')}</span><div class="section-head"><h2>${t('Организаторы<br>и партнёры','Կազմակերպիչներ<br>և գործընկերներ')}</h2><p>${t('Проект объединяет образование, культуру и студенческий туризм.','Նախագիծը միավորում է կրթությունը, մշակույթը և ուսանողական զբոսաշրջությունը։')}</p></div><div class="partner-grid">${['Национальный университет архитектуры и строительства Армении','Министерство науки и высшего образования Российской Федерации','Армянский государственный педагогический университет имени Хачатура Абовяна','Северо-Кавказский федеральный университет','Российско-Армянский университет','Программа Студтуризм Минобрнауки России'].map((name,i)=>`<div class="partner"><img src="assets/partner-${i}.webp" alt="${esc(t(name,['Հայաստանի ճարտարապետության և շինարարության ազգային համալսարան','Ռուսաստանի գիտության և բարձրագույն կրթության նախարարություն','Խաչատուր Աբովյանի անվան հայկական պետական մանկավարժական համալսարան','Հյուսիսկովկասյան դաշնային համալսարան','Ռուս-հայկական համալսարան','Ռուսաստանի գիտության և բարձրագույն կրթության նախարարության «Ստուդտուրիզմ» ծրագիր'][i]))}" loading="lazy" width="400" height="150"></div>`).join('')}</div></div></section></main><footer class="footer"><div class="wrap">${logo()}<p>${t('«Барев, Ереван: где прошлое встречает будущее» · Культурно-образовательный маршрут','«Բարև, Երևան․ որտեղ անցյալը հանդիպում է ապագային» · Մշակութային և կրթական երթուղի')}</p><a class="text-link" href="#home">${t('Наверх','Դեպի վեր')} ↑</a></div></footer>`;
 enrichContent();bind();renderChapters();renderDay();window.SiteMotion?.mount();
}
function chapterHtml(dayIndex){
 const d=days[dayIndex],r=ROUTES[dayIndex];
 return `<details class="day-chapter" id="chapter-${dayIndex}" style="--accent:${chapterColors[dayIndex]}" ${dayIndex===0?'open':''}><summary class="chapter-heading"><span class="chapter-number">0${dayIndex+1}</span><h3>${pair(d.title)}</h3><span class="chapter-tags">${stages.map(st=>`<span>${pair(st)}</span>`).join('')}</span><span class="chapter-toggle" aria-hidden="true">+</span></summary><div class="chapter-body"><div class="chapter-intro"><div class="ill">${keyArt(dayIndex)}</div><span class="key-badge">${t('Ключ','Բանալի')} · ${pair(d.key)}</span><h4>${pair(d.subtitle)}</h4><p>${pair(d.idea)}</p><p class="day-context">${pair(keyStories[dayIndex])}</p><div class="day-takeaway"><span>${t("В фокусе дня","Օրվա ուշադրության կենտրոնում")}</span><p>${pair(d.stageTitles[0])} → ${pair(d.stageTitles[1])} → ${pair(d.stageTitles[2])}</p></div><img class="day-cover" src="assets/${d.image}.webp" alt="${pair(d.title)} · ${t('Ереван','Երևան')}" loading="lazy" width="900" height="600">${d.practice?`<div class="practice">${pair(d.practice)}</div>`:''}</div><div class="chapter-timeline">${stages.map((stage,k)=>`<article class="stage-card"><div class="stage-meta"><span>0${k+1} / ${pair(stage)}</span><span>${k===0?(dayIndex===0?'09:00–12:00':'10:00–12:00'):k===1?'13:00–15:00':'15:00–17:00'}</span></div><h4>${pair(d.stageTitles[k])}</h4><p>${pair(d.stageCopy[k])}</p><div class="places">${r.stops.map((stop,j)=>stop.stage===k?`<details class="place" id="place-${dayIndex}-${j}"><summary><span>${esc(pair(stop.name))}${wowStops[dayIndex].includes(j)?` <span class="wow">WOW</span>`:''}</span></summary><div class="place-content">${stop.image?`<img src="${esc(stop.image)}" alt="${esc(pair(stop.name))}" loading="lazy" width="600" height="400">`:''}<p>${esc(pair(stop.description))}</p><p class="muted">${t('Символ','Խորհրդանիշ')} · ${esc(pair(stop.symbol))}</p><button class="map-link" data-route-day="${dayIndex}" data-stop="${j}">${t('Показать на карте','Ցույց տալ քարտեզի վրա')} ↗</button></div></details>`:'').join('')}</div><button class="stage-map" data-route-day="${dayIndex}" data-show-stage="${k}">${t('Показать этап на карте','Ժամանակահատվածը քարտեզի վրա')} ↗</button>${k===0?`<p class="meal">${t('Обед','Ճաշ')} · 12:00–13:00</p>`:''}${k===2?`<p class="meal">${t('Ужин','Ընթրիք')} · 17:30–18:30</p>`:''}</article>`).join('')}</div></div></details>`;
}
function renderChapters(){
 const panel=document.getElementById('day-chapters');panel.innerHTML=days.map((_,i)=>chapterHtml(i)).join('');
 panel.querySelectorAll('[data-stop]').forEach(b=>b.onclick=()=>showMap(-1,+b.dataset.stop,+b.dataset.routeDay));
 panel.querySelectorAll('[data-show-stage]').forEach(b=>b.onclick=()=>showMap(+b.dataset.showStage,null,+b.dataset.routeDay));
 document.querySelectorAll('.key-art').forEach(link=>link.onclick=e=>{e.preventDefault();const chapter=document.querySelector(link.hash);if(window.SiteMotion)window.SiteMotion.expand(chapter,true);else chapter.open=true;chapter.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});
}
function renderDay(){
 const d=days[currentDay],r=ROUTES[currentDay];
 document.querySelectorAll('[data-map-day]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.mapDay===currentDay));
 document.getElementById('open-map').href=r.path;
 const frame=document.getElementById('map-frame');frame.title=t('Карта дня ','Օրվա քարտեզ՝ ')+(currentDay+1)+' — '+pair(d.title);frame.src=r.path+"?v=5";
 document.getElementById('selected-stop').textContent='';syncFilters();
}
function syncFilters(){document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.stage===currentStage));}
function mapSend(type,extra={}){const f=document.getElementById('map-frame');f?.contentWindow?.postMessage({source:'barev-parent',type,...extra},location.origin);}
function configureMap(){const r=ROUTES[currentDay];mapSend('configure',{lang,stage:currentStage,stops:r.stops.map(s=>({name:pair(s.name),description:pair(s.description),stage:pair(stages[s.stage]),symbol:pair(s.symbol)})),title:pair(days[currentDay].title)});if(pendingStop!==null){mapSend('focus',{index:pendingStop});}}
function showMap(stage,index=null,dayIndex=currentDay){
 const changed=currentDay!==dayIndex;currentDay=dayIndex;currentStage=stage;pendingStop=index;
 if(changed)renderDay();else{syncFilters();mapSend('filter',{stage});if(index!==null){mapSend('focus',{index});pendingStop=null;}}
 if(index!==null)document.getElementById('selected-stop').textContent=pair(ROUTES[currentDay].stops[index].name);
 document.getElementById('route-map').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
}
function bind(){
 document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{const anchor=nav.map(n=>document.getElementById(n[0])).filter(el=>el.getBoundingClientRect().top<150).at(-1)?.id;lang=b.dataset.lang;try{localStorage.setItem('barev-lang',lang);}catch{}render();if(anchor)document.getElementById(anchor).scrollIntoView({behavior:'instant'});});
 document.querySelector('.menu-button').onclick=e=>{const b=e.currentTarget;const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',open);b.setAttribute('aria-label',open?t('Закрыть меню','Փակել ընտրացանկը'):t('Открыть меню','Բացել ընտրացանկը'));b.textContent=open?'×':'☰';document.querySelector('.nav').classList.toggle('open',open);};
 document.querySelectorAll('.nav a').forEach(a=>a.onclick=()=>{document.querySelector('.nav').classList.remove('open');const b=document.querySelector('.menu-button');b.setAttribute('aria-expanded','false');b.setAttribute('aria-label',t('Открыть меню','Բացել ընտրացանկը'));b.textContent='☰';});
 document.querySelectorAll('[data-map-day]').forEach(b=>b.onclick=()=>{currentDay=+b.dataset.mapDay;currentStage=-1;pendingStop=null;renderDay();});
 document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{currentStage=+b.dataset.stage;pendingStop=null;syncFilters();mapSend('filter',{stage:currentStage});});
 document.getElementById('map-frame').onload=configureMap;
 navObserver=new IntersectionObserver(entries=>entries.forEach(en=>{if(en.isIntersecting){document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+en.target.id));}}),{rootMargin:'-10% 0px -60% 0px'});nav.forEach(n=>navObserver.observe(document.getElementById(n[0])));
}
window.addEventListener('message',e=>{const f=document.getElementById('map-frame');if(e.origin!==location.origin||e.source!==f?.contentWindow||e.data?.source!=='barev-map')return;if(e.data.type==='ready')configureMap();if(e.data.type==='selected'){const index=e.data.index;const stop=ROUTES[currentDay].stops[index];if(!stop)return;document.getElementById('selected-stop').textContent=t('На карте: ','Քարտեզի վրա՝ ')+pair(stop.name);document.getElementById('chapter-'+currentDay).open=true;document.querySelectorAll('#chapter-'+currentDay+' .place').forEach((p,i)=>{p.open=i===index;});}});
render();
